def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # For each endpoint of an edge bar, project inward in color 9.
    # A marker 9 is converted to 4 and the ray stops there.
    for r, dr in ((0, 1), (h - 1, -1)):
        c = 0
        while c < w:
            if grid[r][c] != 5:
                c += 1
                continue
            a = c
            while c < w and grid[r][c] == 5:
                c += 1
            b = c - 1
            for x in (a, b):
                y = r + dr
                while 0 <= y < h:
                    if grid[y][x] == 9:
                        out[y][x] = 4
                        break
                    if grid[y][x] == 3:
                        out[y][x] = 9
                    y += dr
    return out

