def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # On each side, edge color marks the background and edge-line color the
    # ray color. The projection follows every edge seed inward, stopping at
    # any distinct object (which becomes 4); preserve the seeds themselves.
    for r in range(h):
        if grid[r][0] != 6:
            source=grid[r][0]
            ray=grid[r][1] if w>1 and grid[r][1] != source else None
            if ray is not None:
                for c in range(1,w):
                    if grid[r][c] == source: out[r][c]=ray
                    elif grid[r][c] != ray:
                        out[r][c]=4; break
        if grid[r][w-1] != 6:
            source=grid[r][w-1]
            ray=grid[r][w-2] if w>1 and grid[r][w-2] != source else None
            if ray is not None:
                for c in range(w-2,-1,-1):
                    if grid[r][c] == source: out[r][c]=ray
                    elif grid[r][c] != ray:
                        out[r][c]=4; break
    return out
